"async function saveDeviceLanguage(wanted){\n"
"    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);\n"
"    try{\n"
"        const info=await fetch('/api/info',{cache:'no-store',signal:controller.signal});\n"
"        if(!info.ok)throw Error(t('网页已切换，小屏尚未同步，请重试'));\n"
"        const before=await info.json();\n"
"        if(!Number.isInteger(before.revision)||before.revision<0)throw Error(t('语言响应无效'));\n"
"        const response=await fetch('/api/language',{method:'POST',cache:'no-store',signal:controller.signal,\n"
"            headers:{'Content-Type':'application/json','X-XH-Language':'1','X-Lingxi-LAN':'1'},body:JSON.stringify({revision:before.revision,language:wanted})});\n"
"        if(!response.ok){const e=Error(t(response.status===409?'设备配置已变化，语言未同步。请重试；其他修改仍保留。':'网页已切换，小屏尚未同步，请重试'));e.conflict=response.status===409;throw e;}\n"
"        const result=await response.json();\n"
"        if(!Number.isInteger(result.revision)||result.revision<before.revision||result.language!==wanted)throw Error(t('语言响应无效'));\n"
"        return {...result,previousRevision:before.revision};\n"
"    }finally{clearTimeout(timer);}\n"
"}\n"
"function setupAppearance(){const select=document.getElementById('appearance');if(!select)return;select.onchange=()=>{if(select.value==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.setAttribute('data-theme',select.value);};}\n"
"\n"
"setupAppearance();applyLanguage();\n"
"const $=id=>document.getElementById(id),encoder=new TextEncoder();let busy=false,alive=true,pollTimer,languageChosen=false,statusSource='选择网络或填写 SSID，然后保存。';\n"
"const setupLinks=new Map(Array.from(document.querySelectorAll('a[href^=\"/standalone\"]'),link=>[link,link.getAttribute('href')]));\n"
"let infoSnapshot;\n"
"function renderIdentity(data){$('identity').textContent=(data.ip==='0.0.0.0'?t('等待联网'):data.ip)+' · '+data.fw;}\n"
"$('pageLanguage').value=uiEnglish?1:0;\n"
"function status(text){statusSource=text;$('status').textContent=t(text);}\n"
"function controls(){for(const id of ['scan','ssid','password','connect','refresh','pageLanguage','languageRetry'])$(id).disabled=busy;}\n"
"async function request(path,options={}){const r=await fetch(path,{cache:'no-store',...options,signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error(uiEnglish?'Request failed ('+r.status+')':'请求失败（'+r.status+'）');return r;}\n"
"function privateIP(ip){const bytes=String(ip).split('.');if(bytes.length!==4||bytes.some(b=>!/^\\d{1,3}$/.test(b)||Number(b)>255))return false;const [a,b]=bytes.map(Number);return a===10||(a===192&&b===168)||(a===172&&b>=16&&b<=31);}\n"
"async function info(){const data=await request('/api/info').then(r=>r.json());if(!alive)return false;infoSnapshot=data;if(!languageChosen){uiEnglish=data.language===1;$('pageLanguage').value=uiEnglish?1:0;}applyLanguage();if(!languageChosen)languageStatus('网页与小屏使用同一语言，切换后自动保存。');status(statusSource);renderIdentity(data);\n"
"if(data.wifi_connected===true&&privateIP(data.ip)){\n"
"for(const [link,path] of setupLinks)link.href='http://'+data.ip+path;\n"
"$('lanAddress').textContent='http://'+data.ip+'/standalone';$('handoff').hidden=false;status('Wi-Fi 已连接。切回同一网络，扫描新二维码继续配置。');clearTimeout(pollTimer);return true;\n"
"}return false;}\n"
"async function waitForConnection(attempt=0){if(!alive)return;try{if(await info())return;}catch{/* AP can close before this response; screen QR remains available. */}if(!alive)return;if(attempt>=59){status('暂未确认联网。检查密码后重试；若热点已关闭，请查看屏幕的新二维码。');return;}pollTimer=setTimeout(()=>waitForConnection(attempt+1),1000);}\n"
"async function switchLanguage(){\n"
"    if(busy)return;\n"
"    languageChosen=true;uiEnglish=$('pageLanguage').value==='1';applyLanguage();status(statusSource);if(infoSnapshot)renderIdentity(infoSnapshot);\n"
"    busy=true;controls();languageStatus('正在同步小屏语言…');\n"
"    try{const result=await saveDeviceLanguage(uiEnglish?1:0);if(!alive)return;if(infoSnapshot)Object.assign(infoSnapshot,{language:result.language,revision:result.revision});languageStatus('网页与小屏语言已同步');}\n"
"    catch(e){if(alive)languageStatus(e.name==='AbortError'?t('网页已切换，小屏尚未同步，请重试'):e.message,true);}\n"
"    finally{busy=false;if(alive)controls();}\n"
"}\n"
"$('pageLanguage').onchange=switchLanguage;$('languageRetry').onclick=switchLanguage;\n"
"languageStatus('网页与小屏使用同一语言，切换后自动保存。');\n"
"$('refresh').onclick=()=>info().catch(()=>status('连接超时，请检查设备网络。'));\n"
"$('scan').onclick=async()=>{if(busy)return;busy=true;controls();status('正在扫描附近的 2.4 GHz 网络…');try{let data=await request('/api/wifi/scan?start=1').then(r=>r.json());for(let i=0;data.busy&&i<24&&alive;i++){await new Promise(resolve=>setTimeout(resolve,500));data=await request('/api/wifi/scan').then(r=>r.json());}if(!alive)return;if(data.busy||data.error)throw Error(t('扫描失败，请稍后重试或手动填写 SSID。'));$('networks').replaceChildren();for(const network of data.networks||[]){if(!network.ssid)continue;const button=document.createElement('button');button.type='button';const name=document.createElement('span');name.textContent=network.ssid;const signal=document.createElement('small');signal.textContent=network.rssi+' dBm';button.append(name,signal);button.onclick=()=>{if($('ssid').value!==network.ssid)$('password').value='';$('ssid').value=network.ssid;$('password').focus();};$('networks').append(button);}status(data.networks?.length?'请选择网络并填写密码。':'没有发现网络，可手动填写 SSID。');}catch(e){if(alive)status(e.message);}finally{busy=false;if(alive)controls();}};\n"
"$('wifiForm').onsubmit=async event=>{event.preventDefault();if(busy)return;const ssid=$('ssid').value,password=$('password').value,n=encoder.encode(password).length;\n"
"if(!ssid||encoder.encode(ssid).length>32||ssid.includes('\\0'))return status('SSID 必须为 1–32 个 UTF-8 字节。');\n"
"if(password.includes('\\0')||!(n===0||(n>=8&&n<=63)||(n===64&&/^[0-9a-f]{64}$/i.test(password))))return status('密码应为 8–63 个字节，开放网络可留空。');\n"
"busy=true;controls();clearTimeout(pollTimer);$('handoff').hidden=true;try{await request('/wifi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-XH-WiFi':'1'},body:new URLSearchParams({ssid,password}).toString()});status('网络已保存，正在等待设备取得局域网 IP…');pollTimer=setTimeout(()=>waitForConnection(),1000);}catch(e){if(alive)status(e.message);}finally{$('password').value='';busy=false;if(alive)controls();}};\n"
"$('ssid').oninput=()=>{$('password').value='';};window.addEventListener('pagehide',()=>{alive=false;$('password').value='';clearTimeout(pollTimer);});info().catch(()=>status('连接超时，请检查设备网络。'));\n"
"</script></body></html>\n"
"\n";
